package mz.uem.restaurante.ui;
import java.awt.*; import javax.swing.*; import javax.swing.table.DefaultTableModel;
public class PainelLotesStock extends JPanel { private final DefaultTableModel modelo=new DefaultTableModel(new Object[]{"Item","Fornecedor","Lote","Quantidade","Validade","Estado"},0){public boolean isCellEditable(int r,int c){return false;}}; private final JTable tabela=new JTable(modelo); public PainelLotesStock(){setLayout(new BorderLayout(0,14));setBorder(BorderFactory.createEmptyBorder(20,24,20,24));JPanel topo=new JPanel(new BorderLayout());topo.setOpaque(false);topo.add(Ui.titulo("Lotes e validade"),BorderLayout.WEST);Ui.prepararTabela(tabela);JScrollPane scroll=new JScrollPane(tabela);Ui.card(scroll);JPanel acoes=new JPanel(new FlowLayout(FlowLayout.LEFT));acoes.setOpaque(false);JButton novo=Ui.botao("Novo lote",Ui.DESTAQUE), alerta=Ui.botaoSecundario("Ver validade");acoes.add(novo);acoes.add(alerta);novo.addActionListener(e->novo());alerta.addActionListener(e->JOptionPane.showMessageDialog(this,"São apresentados os lotes próximos do vencimento.","Validade",JOptionPane.INFORMATION_MESSAGE));add(topo,BorderLayout.NORTH);add(scroll,BorderLayout.CENTER);add(acoes,BorderLayout.SOUTH);} private void novo(){modelo.addRow(new Object[]{"Novo item","Fornecedor","Lote-001","0","dd/MM/yyyy","Normal"});}}
